// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.infrastructureimport timber.log.Timberimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.withContext/** * NOUS — Battery Adaptive Controller (Module 6 v4 — Step 6.7). * * Adapts vision FPS based on battery level, per strategy v4 §"Issue 11: * Battery Drain". * * ## Adaptive FPS (per strategy v4 §"Issue 11") * * | Battery Level | Detection FPS | Captioning | Vision Mode | * |--------------|--------------|------------|-------------| * | 80-100% | 20 FPS | On-demand | Full | * | 50-80% | 15 FPS | On-demand | Full | * | 20-50% | 10 FPS | Disabled | Detection only | * | < 20% | 0 FPS (disabled) | Disabled | Text-only mode | * * ## User Feedback * * When battery drops below 20%: * > "Battery is low. Switching to text-only mode. Vision disabled." * * When battery drops below 50%: * > "Battery is low. Switching to power-saving mode (lower FPS)." * * ## Integration * * [ObjectDetectionEngine] observes [batteryState] and caps its target FPS. * [OmniSlmRuntime] checks [canRunCaptioning] before running image captioning. * * ## Testability * * [BatteryProbe] abstracts Android's BatteryManager. Tests inject * [FakeBatteryProbe] to simulate any battery level. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Issue 11: Battery Drain</a> */class BatteryAdaptiveController(    private val probe: BatteryProbe,    private val pollIntervalMs: Long = DEFAULT_POLL_INTERVAL_MS,) {    private val _batteryState = MutableStateFlow(BatteryState.FULL)    val batteryState: StateFlow<BatteryState> = _batteryState.asStateFlow()    /** Current battery level (0-100), or null if unavailable. */    @Volatile    private var currentBatteryPercent: Int? = null    /** True if the device is currently charging. */    @Volatile    private var isCharging: Boolean = false    /**     * Start polling the battery level.     */    suspend fun startPolling(dispatcher: CoroutineDispatcher) = withContext(dispatcher) {        Timber.tag(TAG).i("Battery polling started (interval=${pollIntervalMs}ms).")        while (true) {            val percent = try {                probe.getBatteryPercent()            } catch (t: Throwable) {                Timber.tag(TAG).w("Failed to read battery — assuming 100%.", t)                100            }            val charging = try {                probe.isCharging()            } catch (t: Throwable) {                false            }            currentBatteryPercent = percent            isCharging = charging            val newState = classifyBattery(percent, charging, _batteryState.value)            if (newState != _batteryState.value) {                Timber.tag(TAG).w("Battery state transition: ${_batteryState.value} → $newState " +                    "(battery=${percent}%, charging=${charging}).")                _batteryState.value = newState            }            delay(pollIntervalMs)        }    }    /**     * Classify battery level into a [BatteryState].     *     * When charging, always returns FULL (or at least POWER_SAVING) — no need     * to conserve battery when plugged in.     */    internal fun classifyBattery(        percent: Int,        charging: Boolean,        currentState: BatteryState,    ): BatteryState {        // If charging, don't throttle (unless critically low).        if (charging && percent > 20) {            return BatteryState.FULL        }        return when {            percent >= 80 -> BatteryState.FULL            percent >= 50 -> BatteryState.MODERATE            percent >= 20 -> BatteryState.LOW            else -> BatteryState.CRITICAL        }    }    /**     * Get the adaptive target FPS for the current battery state.     *     * [ObjectDetectionEngine] uses this to cap its target FPS.     */    fun getAdaptiveTargetFps(): Int = when (_batteryState.value) {        BatteryState.FULL -> 20        BatteryState.MODERATE -> 15        BatteryState.LOW -> 10        BatteryState.CRITICAL -> 0  // Vision disabled    }    /**     * Check if image captioning should run.     *     * Captioning is disabled below 50% battery (it's the most expensive vision operation).     */    fun canRunCaptioning(): Boolean = when (_batteryState.value) {        BatteryState.FULL, BatteryState.MODERATE -> true        BatteryState.LOW, BatteryState.CRITICAL -> false    }    /**     * Check if vision should run at all.     *     * Vision is fully disabled below 20% battery (text-only mode).     */    fun isVisionEnabled(): Boolean = _batteryState.value != BatteryState.CRITICAL    /**     * Get the adaptive vision configuration for the current battery state.     */    fun getAdaptiveConfig(): BatteryVisionConfig = when (_batteryState.value) {        BatteryState.FULL -> BatteryVisionConfig(            targetFps = 20,            captioningEnabled = true,            faceDetectionEnabled = true,            ocrEnabled = true,            visionMode = VisionMode.FULL,        )        BatteryState.MODERATE -> BatteryVisionConfig(            targetFps = 15,            captioningEnabled = true,            faceDetectionEnabled = true,            ocrEnabled = true,            visionMode = VisionMode.FULL,        )        BatteryState.LOW -> BatteryVisionConfig(            targetFps = 10,            captioningEnabled = false,  // Disable captioning (most expensive)            faceDetectionEnabled = false,            ocrEnabled = true,            visionMode = VisionMode.DETECTION_ONLY,        )        BatteryState.CRITICAL -> BatteryVisionConfig(            targetFps = 0,            captioningEnabled = false,            faceDetectionEnabled = false,            ocrEnabled = false,            visionMode = VisionMode.TEXT_ONLY,        )    }    /** Get current battery percent (0-100). */    fun getCurrentBatteryPercent(): Int? = currentBatteryPercent    /** True if device is charging. */    fun isCharging(): Boolean = isCharging    /** Get current battery state. */    fun getCurrentState(): BatteryState = _batteryState.value    /** User-facing message for the current battery state. */    fun getUserMessage(): String? = when (_batteryState.value) {        BatteryState.FULL -> null        BatteryState.MODERATE -> null        BatteryState.LOW -> "Battery is low. Switching to power-saving mode (lower FPS)."        BatteryState.CRITICAL -> "Battery is low. Switching to text-only mode. Vision disabled."    }    private companion object {        private const val TAG = "BatteryAdaptive"        private const val DEFAULT_POLL_INTERVAL_MS = 5000L  // 5 seconds    }}// ──────────────────────────────────────────────────────────────────────────/** Battery state tiers. */enum class BatteryState(val displayName: String, val batteryRange: String) {    /** 80-100% — full vision, 20 FPS. */    FULL("Full Battery", "80-100%"),    /** 50-80% — full vision, 15 FPS. */    MODERATE("Moderate Battery", "50-80%"),    /** 20-50% — detection only, 10 FPS, captioning disabled. */    LOW("Low Battery", "20-50%"),    /** < 20% — vision disabled, text-only mode. */    CRITICAL("Critical Battery", "< 20%");}/** Vision mode (driven by battery state). */enum class VisionMode(val displayName: String) {    /** All engines active (detection + captioning + OCR + face). */    FULL("Full Vision"),    /** Detection + OCR only (captioning + face disabled). */    DETECTION_ONLY("Detection Only"),    /** Vision fully disabled (text-only mode). */    TEXT_ONLY("Text Only (Vision Disabled)"),}/** Adaptive vision configuration based on battery state. */data class BatteryVisionConfig(    val targetFps: Int,    val captioningEnabled: Boolean,    val faceDetectionEnabled: Boolean,    val ocrEnabled: Boolean,    val visionMode: VisionMode,) {    /** True if vision is fully disabled. */    val isVisionDisabled: Boolean        get() = visionMode == VisionMode.TEXT_ONLY}// ──────────────────────────────────────────────────────────────────────────/** * Battery probe interface — abstracts Android BatteryManager. * * Production: [AndroidBatteryProbe] wraps BatteryManager + BatteryManager.EXTRA_LEVEL. * Tests: [FakeBatteryProbe] returns canned battery levels. */interface BatteryProbe {    /** Get the current battery level (0-100). */    suspend fun getBatteryPercent(): Int    /** True if the device is currently charging. */    suspend fun isCharging(): Boolean}